use crate::{roots::{self,Root,Domain},members::{Action,Stage,DurableReceipt,TrustedState,Manifest,MemberContent}};
use std::{fs::{self,File},path::PathBuf,os::unix::fs::{PermissionsExt,symlink},time::Duration,collections::BTreeMap,sync::atomic::{AtomicU64,Ordering}};
use serde_json::json;
use base64::Engine;
static COUNTER:AtomicU64=AtomicU64::new(0);
pub(crate) struct Fixture{pub(crate) base:PathBuf,pub(crate) root:Root}
impl Fixture{
 pub(crate) fn new()->Self{Self::with_scope(None)}
 pub(crate) fn with_scope(selected_scope:Option<roots::ExecutionScope>)->Self{
  let parent=PathBuf::from(std::env::var("TMPDIR").unwrap());let base=parent.join(format!("member-fixture-{}-{}",std::process::id(),COUNTER.fetch_add(1,Ordering::SeqCst)));
  fs::create_dir(&base).unwrap();fs::set_permissions(&base,fs::Permissions::from_mode(0o700)).unwrap();
  let path=base.join("root");fs::create_dir(&path).unwrap();fs::set_permissions(&path,fs::Permissions::from_mode(0o700)).unwrap();
  let policies=["alias","ancestors","acl"].map(|role|{let name=format!("{role}-fixture.json");let raw=format!("{{\"scope\":\"isolated fixture {role}, no host authority\"}}");fs::write(base.join(&name),raw.as_bytes()).unwrap();roots::Binding{kind:"evidence".into(),root_id:"fixture-control".into(),relative_path:name,sha256:roots::hash(raw.as_bytes()),size_bytes:raw.len() as u64}});
  let activation_raw=serde_json::to_vec(&json!({"fixture_root":path,"namespace_epoch":9})).unwrap();fs::write(base.join("activation.json"),&activation_raw).unwrap();
  let default_scope=roots::ExecutionScope{activation_binding:roots::Binding{kind:"execution".into(),root_id:"fixture-control".into(),relative_path:"activation.json".into(),sha256:roots::hash(&activation_raw),size_bytes:activation_raw.len() as u64},store_id:"fixture-store".into(),instance_id:"fixture-instance".into(),slot_epoch:1,principal_ref:"fixture-principal".into()};
  let mut selection=Root::capture_fixture(&path,"owned-root",policies,selected_scope.unwrap_or(default_scope)).unwrap();selection.namespace_epoch=9;let root=Root::open(selection,Domain::Fixture).unwrap();Self{base,root}
 }
 pub(crate) fn receipt(&self,stage:&mut Stage<'_>){let t=stage.pending().unwrap().clone();let d=File::open(&self.base).unwrap();let receipt=DurableReceipt::persist_fixture(&t,&d,&format!("receipt-{}.json",t.sequence)).unwrap();stage.acknowledge(receipt).unwrap();}
}
// Owned fixtures are retained on failure; successful tests remove only their
// exclusive directory. Production deletion is absent from the candidate API.
impl Drop for Fixture{fn drop(&mut self){if !std::thread::panicking(){fs::remove_dir_all(&self.base).unwrap();}}}
fn action(verb:&str,sequence:u64,payload:serde_json::Value)->Action{Action{request:json!({"verb":verb,"sequence":sequence,"operation_id":"operation-1","payload":payload}),wire:roots::hash(format!("{verb}-{sequence}-{payload}").as_bytes()),fingerprint:roots::hash(b"immutable operation"),domain:Domain::Fixture,stage_binding:None}}
fn scoped(mut action:Action,scope:&roots::ExecutionScope)->Action{action.request["activation_binding"]=serde_json::to_value(&scope.activation_binding).unwrap();action.request["store_id"]=json!(scope.store_id);action.request["instance_id"]=json!(scope.instance_id);action.request["slot_epoch"]=json!(scope.slot_epoch);action.request["principal_ref"]=json!(scope.principal_ref);action}
pub(crate) fn create_for(f:&Fixture)->Action{scoped(action("create_stage",0,json!({"root_id":"owned-root","stage_name":"stage-1","max_bytes":65536})),&f.root.selection().execution_scope)}
fn chunk_for(stage:&Stage<'_>,seq:u64,path:&str,full:&[u8],offset:u64,raw:&[u8])->Action{let mut a=action("write_member",seq,json!({"root_id":"owned-root","member":path,"preimage_binding":null,"full_sha256":roots::hash(full),"full_length":full.len(),"offset":offset,"length":raw.len(),"chunk_sha256":roots::hash(raw),"bytes_base64":base64::engine::general_purpose::STANDARD.encode(raw)}));a.stage_binding=stage.stage_binding().cloned();scoped(a,stage.execution_scope())}
fn manifest(stage:&Stage<'_>,generation:&str)->Vec<u8>{let s=stage.snapshot().unwrap();let members:BTreeMap<_,_>=s.members.iter().map(|(p,m)|(p.clone(),MemberContent{sha256:m.full_sha256.clone(),size_bytes:m.full_length})).collect();serde_json::to_vec(&serde_json::to_value(Manifest{schema_version:"lab-member-generation/v1".into(),root_id:s.root_id,operation_id:s.operation_id,fingerprint:s.fingerprint,stage_identity:s.stage_identity,generation_name:generation.into(),members}).unwrap()).unwrap()}
fn subject_for(stage:&Stage<'_>,verb:&str,seq:u64,m:&[u8])->Action{let mut a=action(verb,seq,json!({"root_id":"owned-root","subject_binding":{"kind":"execution","root_id":"fixture","relative_path":"manifest.json","sha256":roots::hash(m),"size_bytes":m.len()}}));a.stage_binding=stage.stage_binding().cloned();scoped(a,stage.execution_scope())}
#[test]fn pending_requires_exact_historical_durable_receipt(){let f=Fixture::new();let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();let mut s=Stage::create(&hold,&create_for(&f)).unwrap();assert!(s.snapshot().is_err());assert!(s.write_member(&chunk_for(&s,1,"a",b"x",0,b"x")).is_err());f.receipt(&mut s);s.write_member(&chunk_for(&s,1,"a",b"x",0,b"x")).unwrap();assert!(s.snapshot().is_err());let mut t=s.pending().unwrap().clone();t.sequence=99;let receipt=DurableReceipt::persist_fixture(&t,&File::open(&f.base).unwrap(),"wrong.json").unwrap();assert!(s.acknowledge(receipt).is_err());f.receipt(&mut s);assert_eq!(s.snapshot().unwrap().members["a"].ranges[0].sequence,1);}
#[test]fn contiguous_chunk_restart_seal_and_no_replace_publish(){let f=Fixture::new();let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();let mut s=Stage::create(&hold,&create_for(&f)).unwrap();f.receipt(&mut s);s.write_member(&chunk_for(&s,1,"nested/member",b"abcd",0,b"ab")).unwrap();f.receipt(&mut s);let snap=s.snapshot().unwrap();drop(s);let mut s=Stage::restore(&hold,TrustedState::fixture(snap).unwrap()).unwrap();s.write_member(&chunk_for(&s,2,"nested/member",b"abcd",2,b"cd")).unwrap();f.receipt(&mut s);let m=manifest(&s,"generation-1");s.seal(&subject_for(&s,"seal_stage",3,&m),&m).unwrap();f.receipt(&mut s);s.publish(&subject_for(&s,"commit_generation",4,&m),&m).unwrap();assert!(s.snapshot().is_err());f.receipt(&mut s);assert_eq!(fs::read(f.base.join("root/generation-1/nested/member")).unwrap(),b"abcd");assert!(!f.base.join("root/stage-1").exists());assert!(s.write_member(&chunk_for(&s,5,"another",b"x",0,b"x")).is_err());}
#[test]fn gap_overlap_and_renewed_content_refuse(){for mode in 0..3{let f=Fixture::new();let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();let mut s=Stage::create(&hold,&create_for(&f)).unwrap();f.receipt(&mut s);s.write_member(&chunk_for(&s,1,"a",b"abcd",0,b"ab")).unwrap();f.receipt(&mut s);let next=match mode{0=>chunk_for(&s,2,"a",b"abcd",3,b"d"),1=>chunk_for(&s,2,"a",b"abcd",0,b"ab"),_=>chunk_for(&s,2,"a",b"abXY",2,b"XY")};assert!(s.write_member(&next).is_err());assert_eq!(fs::read(f.base.join("root/stage-1/a")).unwrap(),b"ab");assert!(s.pending().is_none());}}
#[test]fn stage_collision_preserves_empty_and_populated_foreign(){for populated in [false,true]{let f=Fixture::new();fs::create_dir(f.base.join("root/stage-1")).unwrap();if populated{fs::write(f.base.join("root/stage-1/foreign"),b"foreign").unwrap();}let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();assert!(Stage::create(&hold,&create_for(&f)).is_err());if populated{assert_eq!(fs::read(f.base.join("root/stage-1/foreign")).unwrap(),b"foreign");}}}
#[test]fn publication_empty_directory_collision_preserved(){let f=Fixture::new();let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();let mut s=Stage::create(&hold,&create_for(&f)).unwrap();f.receipt(&mut s);let m=manifest(&s,"generation-1");s.seal(&subject_for(&s,"seal_stage",1,&m),&m).unwrap();f.receipt(&mut s);fs::create_dir(f.base.join("root/generation-1")).unwrap();let before=std::os::unix::fs::MetadataExt::ino(&fs::metadata(f.base.join("root/generation-1")).unwrap());assert!(s.publish(&subject_for(&s,"commit_generation",2,&m),&m).is_err());assert_eq!(std::os::unix::fs::MetadataExt::ino(&fs::metadata(f.base.join("root/generation-1")).unwrap()),before);assert!(f.base.join("root/stage-1").exists());}
#[test]fn unacknowledged_tail_and_corrupt_ack_range_refuse_restart(){for corrupt in [false,true]{let f=Fixture::new();let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();let mut s=Stage::create(&hold,&create_for(&f)).unwrap();f.receipt(&mut s);s.write_member(&chunk_for(&s,1,"a",b"abcd",0,b"ab")).unwrap();f.receipt(&mut s);let state=s.snapshot().unwrap();if corrupt{fs::write(f.base.join("root/stage-1/a"),b"XX").unwrap();}else{s.write_member(&chunk_for(&s,2,"a",b"abcd",2,b"cd")).unwrap();}drop(s);assert!(Stage::restore(&hold,TrustedState::fixture(state).unwrap()).is_err());assert_eq!(fs::read(f.base.join("root/stage-1/a")).unwrap(),if corrupt{b"XX".to_vec()}else{b"abcd".to_vec()});}}
#[test]fn ancestor_rename_and_named_stage_swap_refuse(){let f=Fixture::new();let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();let mut s=Stage::create(&hold,&create_for(&f)).unwrap();f.receipt(&mut s);fs::rename(f.base.join("root/stage-1"),f.base.join("root/detached")).unwrap();fs::create_dir(f.base.join("root/stage-1")).unwrap();assert!(s.write_member(&chunk_for(&s,1,"a",b"x",0,b"x")).is_err());assert!(!f.base.join("root/detached/a").exists());drop(s);drop(hold);fs::rename(f.base.join("root"),f.base.join("old-root")).unwrap();fs::create_dir(f.base.join("root")).unwrap();assert!(f.root.validate().is_err());}
#[test]fn symlink_hardlink_and_fifo_inventory_refuse_without_blocking(){for kind in 0..3{let f=Fixture::new();let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();let mut s=Stage::create(&hold,&create_for(&f)).unwrap();f.receipt(&mut s);let state=s.snapshot().unwrap();let target=f.base.join("root/stage-1/a");match kind{0=>{symlink(f.base.join("outside"),&target).unwrap();},1=>{fs::write(f.base.join("outside"),b"private inert marker").unwrap();fs::hard_link(f.base.join("outside"),&target).unwrap();},_=>{let c=std::ffi::CString::new(target.to_str().unwrap()).unwrap();assert_eq!(unsafe{libc::mkfifo(c.as_ptr(),0o600)},0);}}assert!(s.write_member(&chunk_for(&s,1,"a",b"x",0,b"x")).is_err());assert!(Stage::restore(&hold,TrustedState::fixture(state).unwrap()).is_err());}}
#[test]fn changed_member_owner_mode_or_hardlink_refuse_ack(){for hardlink in [false,true]{let f=Fixture::new();let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();let mut s=Stage::create(&hold,&create_for(&f)).unwrap();f.receipt(&mut s);s.write_member(&chunk_for(&s,1,"a",b"x",0,b"x")).unwrap();if hardlink{fs::hard_link(f.base.join("root/stage-1/a"),f.base.join("alias")).unwrap();}else{fs::set_permissions(f.base.join("root/stage-1/a"),fs::Permissions::from_mode(0o644)).unwrap();}let t=s.pending().unwrap().clone();let r=DurableReceipt::persist_fixture(&t,&File::open(&f.base).unwrap(),"r.json").unwrap();assert!(s.acknowledge(r).is_err());assert!(s.snapshot().is_err());}}
#[test]fn full_digest_and_incomplete_seal_refuse(){for wrong in [false,true]{let f=Fixture::new();let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();let mut s=Stage::create(&hold,&create_for(&f)).unwrap();f.receipt(&mut s);s.write_member(&chunk_for(&s,1,"a",if wrong{b"XX"}else{b"abcd"},0,b"ab")).unwrap();f.receipt(&mut s);let m=manifest(&s,"generation");assert!(s.seal(&subject_for(&s,"seal_stage",2,&m),&m).is_err());assert!(s.pending().is_none());}}
#[test]fn root_selection_mount_mode_and_fixture_actual_boundary(){let f=Fixture::new();let mut selected=f.root.selection().clone();selected.ancestors.last_mut().unwrap().mount_id+=1;assert!(Root::open(selected,Domain::Fixture).is_err());assert!(Root::open(f.root.selection().clone(),Domain::Actual).is_err());let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();assert!(f.root.exclusive(Duration::from_millis(10)).is_err());drop(hold);fs::set_permissions(f.base.join("root"),fs::Permissions::from_mode(0o777)).unwrap();assert!(f.root.validate().is_err());}
#[test]fn exact_sequence_fingerprint_and_path_refuse(){for mode in 0..4{let f=Fixture::new();let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();let mut s=Stage::create(&hold,&create_for(&f)).unwrap();f.receipt(&mut s);let mut a=chunk_for(&s,1,"a",b"x",0,b"x");match mode{0=>a.request["sequence"]=json!(0),1=>a.fingerprint=roots::hash(b"replacement"),2=>a.request["payload"]["member"]=json!("../outside"),_=>a.request["payload"]["member"]=json!("bad\\name")};assert!(s.write_member(&a).is_err());assert!(!f.base.join("outside").exists());}}

#[test]fn exact_stage_and_policy_bindings_cannot_be_substituted(){let f=Fixture::new();let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();let mut s=Stage::create(&hold,&create_for(&f)).unwrap();f.receipt(&mut s);let mut a=chunk_for(&s,1,"a",b"x",0,b"x");a.stage_binding.as_mut().unwrap().relative_path="different-original.json".into();assert!(s.write_member(&a).is_err());assert!(!f.base.join("root/stage-1/a").exists());let mut selected=s.snapshot().unwrap();selected.acl_binding.relative_path="different-policy.json".into();assert!(Stage::restore(&hold,TrustedState::fixture(selected).unwrap()).is_err());}
#[test]fn empty_and_unicode_members_seal_only_once(){let f=Fixture::new();let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();let mut s=Stage::create(&hold,&create_for(&f)).unwrap();f.receipt(&mut s);s.write_member(&chunk_for(&s,1,"é-😀",b"",0,b"")).unwrap();f.receipt(&mut s);let m=manifest(&s,"unicode-generation");s.seal(&subject_for(&s,"seal_stage",2,&m),&m).unwrap();f.receipt(&mut s);assert!(s.seal(&subject_for(&s,"seal_stage",3,&m),&m).is_err());}

#[test]fn failures_at_write_file_sync_and_parent_sync_preserve_unknown_tail(){for phase in 1..=3{let f=Fixture::new();let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();let mut s=Stage::create(&hold,&create_for(&f)).unwrap();f.receipt(&mut s);let original=s.snapshot().unwrap();crate::members::FAIL_BOUNDARY.with(|v|v.set(phase));let result=s.write_member(&chunk_for(&s,1,"a",b"x",0,b"x"));crate::members::FAIL_BOUNDARY.with(|v|v.set(0));assert!(result.is_err());assert!(s.snapshot().is_err());assert!(s.pending().is_none());drop(s);assert!(Stage::restore(&hold,TrustedState::fixture(original).unwrap()).is_err());assert_eq!(fs::read(f.base.join("root/stage-1/a")).unwrap(),b"x");}}
#[test]fn rename_before_parent_sync_failure_never_acknowledges(){let f=Fixture::new();let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();let mut s=Stage::create(&hold,&create_for(&f)).unwrap();f.receipt(&mut s);let m=manifest(&s,"generation");s.seal(&subject_for(&s,"seal_stage",1,&m),&m).unwrap();f.receipt(&mut s);crate::members::FAIL_BOUNDARY.with(|v|v.set(4));let result=s.publish(&subject_for(&s,"commit_generation",2,&m),&m);crate::members::FAIL_BOUNDARY.with(|v|v.set(0));assert!(result.is_err());assert!(s.snapshot().is_err());assert!(s.pending().is_none());assert!(f.base.join("root/generation").is_dir());assert!(!f.base.join("root/stage-1").exists());}
fn durable_fixture(path:&std::path::Path,raw:&[u8]){use std::io::Write;let mut file=std::fs::OpenOptions::new().write(true).create_new(true).open(path).unwrap();file.write_all(raw).unwrap();file.sync_all().unwrap();File::open(path.parent().unwrap()).unwrap().sync_all().unwrap();}
#[test]fn crash_child_driver(){
 let Some(base)=std::env::var_os("MEMBER_CHILD_BASE")else{return};let base=PathBuf::from(base);assert!(base.starts_with(std::env::var("TMPDIR").unwrap()));
 let selection:roots::Selection=serde_json::from_slice(&fs::read(base.join("selected-root.json")).unwrap()).unwrap();let root=Root::open(selection,Domain::Fixture).unwrap();let hold=root.exclusive(Duration::from_secs(1)).unwrap();
 let snapshot=serde_json::from_slice(&fs::read(base.join("selected-state.json")).unwrap()).unwrap();let mut s=Stage::restore(&hold,TrustedState::fixture(snapshot).unwrap()).unwrap();s.write_member(&chunk_for(&s,1,"a",b"x",0,b"x")).unwrap();
 if std::env::var("MEMBER_CHILD_ACK").unwrap()=="yes"{let r=DurableReceipt::persist_fixture(s.pending().unwrap(),&File::open(&base).unwrap(),"receipt-1.json").unwrap();s.acknowledge(r).unwrap();durable_fixture(&base.join("confirmed-state.json"),&serde_json::to_vec(&s.snapshot().unwrap()).unwrap());}
 durable_fixture(&base.join("child-ready"),b"selected write boundary reached");loop{std::thread::sleep(Duration::from_secs(1));}
}
#[test]fn killed_child_restart_distinguishes_durable_ack_from_unexplained_tail(){
 for ack in [false,true]{let f=Fixture::new();{
 let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();let mut s=Stage::create(&hold,&create_for(&f)).unwrap();f.receipt(&mut s);durable_fixture(&f.base.join("selected-root.json"),&serde_json::to_vec(f.root.selection()).unwrap());durable_fixture(&f.base.join("selected-state.json"),&serde_json::to_vec(&s.snapshot().unwrap()).unwrap());}
 let out=std::fs::OpenOptions::new().write(true).create_new(true).open(f.base.join("child.stdout")).unwrap();let err=std::fs::OpenOptions::new().write(true).create_new(true).open(f.base.join("child.stderr")).unwrap();
 let mut child=std::process::Command::new(std::env::current_exe().unwrap()).args(["--exact","custody_tests::crash_child_driver","--nocapture"]).env_clear().env("TMPDIR",std::env::var("TMPDIR").unwrap()).env("MEMBER_CHILD_BASE",&f.base).env("MEMBER_CHILD_ACK",if ack{"yes"}else{"no"}).stdout(out).stderr(err).spawn().unwrap();
 let start=std::time::Instant::now();while !f.base.join("child-ready").exists(){if let Some(status)=child.try_wait().unwrap(){panic!("child exited before selected boundary {status}: {}",fs::read_to_string(f.base.join("child.stderr")).unwrap());}if start.elapsed()>Duration::from_secs(15){child.kill().unwrap();child.wait().unwrap();panic!("child startup timeout");}std::thread::sleep(Duration::from_millis(5));}
 child.kill().unwrap();child.wait().unwrap();let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();let selected=if ack{"confirmed-state.json"}else{"selected-state.json"};let state=serde_json::from_slice(&fs::read(f.base.join(selected)).unwrap()).unwrap();let result=Stage::restore(&hold,TrustedState::fixture(state).unwrap());assert_eq!(result.is_ok(),ack);assert_eq!(fs::read(f.base.join("root/stage-1/a")).unwrap(),b"x");
 }
}

#[test]fn sealed_exact_manifest_locator_and_target_cannot_change(){let f=Fixture::new();let hold=f.root.exclusive(Duration::from_millis(50)).unwrap();let mut s=Stage::create(&hold,&create_for(&f)).unwrap();f.receipt(&mut s);let m=manifest(&s,"generation-1");s.seal(&subject_for(&s,"seal_stage",1,&m),&m).unwrap();f.receipt(&mut s);let other=manifest(&s,"generation-2");assert!(s.publish(&subject_for(&s,"commit_generation",2,&other),&other).is_err());let mut a=subject_for(&s,"commit_generation",2,&m);a.request["payload"]["subject_binding"]["relative_path"]=json!("other.json");assert!(s.publish(&a,&m).is_err());assert!(!f.base.join("root/generation-1").exists());assert!(!f.base.join("root/generation-2").exists());}
